*/
scwin.goWrite = async function (acptNo, formCd, formVer, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd) {
    /* sdd-asis-lifecycle:begin fn_goWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_searchListReq').set('formCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('formVer', formVer);
    $c.util.getComponent('dma_searchListReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_searchListReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_searchListReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_searchListReq').set('inqOrgnDisclsAcptNo', acptNo);
    $c.util.getComponent('dma_searchListReq').set('ldMktTpCd', ldMktTpCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormVer', formVer);
